#ifndef __KSU_H_HOSTSREDIRECT
#define __KSU_H_HOSTSREDIRECT

static bool ksu_kernel_umount_enabled __read_mostly;

static __always_inline void ksu_hosts_file_redirect(const char __user *filename, int flags, int *fd_ptr)
{
	if (likely(test_thread_flag(TIF_KSU_UNMOUNTABLE)))
		return;

	if (likely(!ksu_module_mounted))
		return;

	if (likely(!ksu_kernel_umount_enabled))
		return;

	constexpr char hf[] = "/system/etc/hosts";

	uint64_t *hf_p = (uint64_t *)hf;
	uint64_t __user *fn_p = (uint64_t __user *)untagged_addr((void *)filename);
	__builtin_prefetch(fn_p);

	uint16_t *last_p = (uint16_t *)((char *)hf + 16);
	uint16_t buf16;
	if (likely(get_user(buf16, (uint16_t __user *)((char __user *)fn_p + 16))))
		return;

	if (likely((buf16 != *last_p)))
		return;

#ifdef CONFIG_64BIT
	uint64_t buf64;
	if (get_user(buf64, &fn_p[1]))
		return;

	if (buf64 != hf_p[1])
		return;

	if (get_user(buf64, &fn_p[0]))
		return;

	if (buf64 != hf_p[0])
		return;
#else
	char cbuf[16];
	if (copy_from_user_retry(cbuf, (void __user *)fn_p, 16))
		return;

	if (!!memcmp_inline(cbuf, hf, 16))
		return;
#endif
	//pr_info("%s: intercepting %s for comm: %s pid: %d\n", __func__, hf, current->comm, current->pid);

	const struct cred *saved = override_creds(ksu_cred);
	struct file *filp = filp_open("/data/adb/hosts", O_RDONLY, 0);
	revert_creds(saved);

	if (IS_ERR(filp))
		return;

	if (!is_compat_task() && force_o_largefile())
		flags |= O_LARGEFILE;

	int fd = get_unused_fd_flags(flags);
	if (fd < 0) {
		fput(filp);
		return;
	}

	fd_install(fd, filp);
	*fd_ptr = fd;

	return;
}

#define __AARCH64_openat 56
#define __ARMEABI_openat 322

#ifdef CONFIG_ARM64
#if LINUX_VERSION_CODE >= KERNEL_VERSION(4, 19, 0)
static syscall_fn_t aarch64_openat __read_mostly = nullptr;
extern long __arm64_sys_openat(const struct pt_regs *regs);
asmlinkage long hook_aarch64_openat(const struct pt_regs *regs)
{
	const char __user *filename = (const char __user *)regs->regs[1];
	int flags = (int)regs->regs[2];

	int fd = -1;
	ksu_hosts_file_redirect(filename, flags, &fd);
	if (fd != -1)
		return fd;
orig_fn:
	return __arm64_sys_openat(regs);
}

#ifdef CONFIG_COMPAT
static syscall_fn_t armeabi_openat __read_mostly = nullptr;
extern long __arm64_compat_sys_openat(const struct pt_regs *regs);
asmlinkage long hook_armeabi_openat(const struct pt_regs *regs)
{
	const char __user *filename = (const char __user *)regs->regs[1];
	int flags = (int)regs->regs[2];

	int fd = -1;
	ksu_hosts_file_redirect(filename, flags, &fd);
	if (fd != -1)
		return fd;
orig_fn:
	return __arm64_compat_sys_openat(regs);
}
#endif // CONFIG_COMPAT
#else /* < 4.19 */
static void *aarch64_openat __read_mostly = nullptr;
asmlinkage long hook_aarch64_openat(int dfd, const char __user *filename, int flags, umode_t mode)
{
	int fd = -1;
	ksu_hosts_file_redirect(filename, flags, &fd);
	if (fd != -1)
		return fd;
orig_fn:
	return sys_openat(dfd, filename, flags, mode);
}

#ifdef CONFIG_COMPAT
extern const void *compat_sys_call_table[];
static void *armeabi_openat __read_mostly = nullptr;
asmlinkage long hook_armeabi_openat(int dfd, const char __user *filename, int flags, umode_t mode)
{
	int fd = -1;
	ksu_hosts_file_redirect(filename, flags, &fd);
	if (fd != -1)
		return fd;
orig_fn:
	return compat_sys_openat(dfd, filename, flags, mode);
}
#endif // CONFIG_COMPAT
#endif  /* < 4.19 */

#else /* ARM */

#if LINUX_VERSION_CODE >= KERNEL_VERSION(4, 19, 0)
static syscall_fn_t armeabi_openat __read_mostly = nullptr;
extern long sys_openat(const struct pt_regs *regs);
asmlinkage long hook_armeabi_openat(const struct pt_regs *regs)
{
	const char __user *filename = (const char __user *)regs->regs[1];
	int flags = (int)regs->regs[2];

	int fd = -1;
	ksu_hosts_file_redirect(filename, flags, &fd);
	if (fd != -1)
		return fd;
orig_fn:
	return sys_openat(regs);
}
#else /* < 4.19 */
static void *armeabi_openat __read_mostly = nullptr;
asmlinkage long hook_armeabi_openat(int dfd, const char __user *filename, int flags, umode_t mode)
{
	int fd = -1;
	ksu_hosts_file_redirect(filename, flags, &fd);
	if (fd != -1)
		return fd;
orig_fn:
	return sys_openat(dfd, filename, flags, mode);
}
#endif /* < 4.19 */
#endif /* ARM */


static void ksu_hostsredirect_init()
{
	// we unhook at boot complete if /data/adb/hosts does not exist
	struct path kpath;
	if (!!kern_path("/data/adb/hosts", 0, &kpath))
		return;

	path_put(&kpath);
	pr_info("ksu_hostsredirect: /data/adb/hosts found! hooking sys_openat \n");
#ifdef CONFIG_ARM64
	read_and_replace_syscall((void *)&aarch64_openat, __AARCH64_openat, (void *)hook_aarch64_openat, (void *)sys_call_table);
# ifdef CONFIG_COMPAT
	read_and_replace_syscall((void *)&armeabi_openat, __ARMEABI_openat, (void *)hook_armeabi_openat, (void *)compat_sys_call_table);
# endif
#else
	read_and_replace_syscall((void *)&armeabi_openat, __AARCH64_openat, (void *)hook_armeabi_openat, (void *)sys_call_table);
#endif
	return;
}

#endif // __KSU_H_HOSTSREDIRECT

static bool ksu_kernel_umount_enabled __read_mostly = true;

static int kernel_umount_feature_get(u64 *value)
{
	*value = ksu_kernel_umount_enabled ? 1 : 0;
	return 0;
}

static int kernel_umount_feature_set(u64 value)
{
	bool enable = value != 0;
	ksu_kernel_umount_enabled = enable;
	pr_info("kernel_umount: set to %d\n", enable);
	return 0;
}

static const struct ksu_feature_handler kernel_umount_handler = {
	.feature_id = KSU_FEATURE_KERNEL_UMOUNT,
	.name = "kernel_umount",
	.get_handler = kernel_umount_feature_get,
	.set_handler = kernel_umount_feature_set,
};

#if LINUX_VERSION_CODE >= KERNEL_VERSION(5, 9, 0)
extern int path_umount(struct path *path, int flags);

static inline void ksu_umount_mnt(const char *mnt, struct path *path, int flags)
{
	int err = path_umount(path, flags);
	if (err)
		pr_info("umount %s failed: %d\n", mnt, err);
}
#else /* we play 'guess if backported' */
static __nocfi inline void ksu_umount_mnt(const char *mnt, struct path *path, int flags)
{
	extern int path_umount(struct path *path, int flags) __weak;
	int err;
#ifdef MODULE
	assume(!path_umount);
#endif
	if (!path_umount)
		goto syscall;

	err = path_umount(path, flags);
	goto out;

syscall:;
	mm_segment_t old_fs = get_fs();
	set_fs(KERNEL_DS);
	err = (int)ksyscall(umount, (const char __user *)mnt, flags);
	set_fs(old_fs);
	path_put(path);  // release caller's ref
out:
	if (err)
		pr_info("umount %s failed: %d\n", mnt, err);
}
#endif

static inline void try_umount(const char *mnt, int flags)
{
	struct path path;
	int err = kern_path(mnt, 0, &path);
	if (err) {
		return;
	}

	if (path.dentry != path.mnt->mnt_root) {
		// it is not root mountpoint, maybe umounted by others already.
		path_put(&path);
		return;
	}

	ksu_umount_mnt(mnt, &path, flags);
}

static inline int ksu_handle_umount(struct cred *new, const struct cred *old)
{
	uid_t new_uid = ksu_get_uid_t(new->uid);
	uid_t old_uid = ksu_get_uid_t(old->uid);

	if (!ksu_kernel_umount_enabled)
		return 0;

	// if there isn't any module mounted, just ignore it!
	if (!ksu_module_mounted)
		return 0;

	// There are 6 scenarios:
	// 1. Normal app: zygote -> appuid
	// 2. Isolated process forked from zygote: zygote -> isolated_process
	// 3. App zygote forked from zygote: zygote -> appuid
	// 4. Webview zygote forked from zygote: zygote -> webview_zygote
	// 5. Isolated process forked from app zygote: appuid -> isolated_process (already handled by 3)
	// 6. Isolated process forked from webview zygote (already handled by 4)
	if (!is_appuid(new_uid) && new_uid != WEBVIEW_ZYGOTE_UID && !is_isolated_process(new_uid))
		return 0;

	if (!ksu_uid_should_umount(new_uid) && !is_isolated_process(new_uid))
		return 0;

	// check old process's selinux context, if it is not zygote, ignore it!
	// because some su apps may setuid to untrusted_app but they are in global mount namespace
	// when we umount for such process, that is a disaster!
	// also handle case 4 and 5
	bool is_zygote_child = is_zygote(old);
	if (!is_zygote_child) {
		pr_info("handle umount ignore non zygote child: %d\n", current->pid);
		return 0;
	}

#ifdef CONFIG_KSU_HOSTSREDIRECT
	set_thread_flag(TIF_KSU_UNMOUNTABLE);
#endif
	// umount the target mnt
	pr_info("handle umount for uid: %d, pid: %d\n", new_uid, current->pid);

	const struct cred *saved = override_creds(ksu_cred);

	struct mount_entry *entry;
	down_read(&mount_list_lock);
	list_for_each_entry (entry, &mount_list, list) {
		pr_info("%s: unmounting: %s flags: 0x%x\n", __func__, entry->umountable, entry->flags);
		try_umount(entry->umountable, entry->flags);
	}
	up_read(&mount_list_lock);

	revert_creds(saved);

	return 0;
}

void __init ksu_kernel_umount_init(void)
{
	if (ksu_register_feature_handler(&kernel_umount_handler)) {
		pr_err("Failed to register kernel_umount feature handler\n");
	}
}

void __exit ksu_kernel_umount_exit(void)
{
	ksu_unregister_feature_handler(KSU_FEATURE_KERNEL_UMOUNT);
}

#if defined(CONFIG_KSU_TAMPER_SYSCALL_TABLE) || defined(CONFIG_KSU_HACK_ARM64_BRANCH_LINK)
#define SUCOMPAT_HOOK_TYPE static __always_inline int
#else
#define SUCOMPAT_HOOK_TYPE int
#endif

#define SU_PATH "/system/bin/su"
#define SH_PATH "/system/bin/sh"

static bool ksu_su_compat_enabled __read_mostly = true;

#if LINUX_VERSION_CODE >= KERNEL_VERSION(4, 4, 0)
static void __user *userspace_stack_buffer(const void *d, size_t len)
{
	// To avoid having to mmap a page in userspace, just write below the stack
	// pointer.
	char __user *p = (void __user *)current_user_stack_pointer() - len;

	return copy_to_user(p, d, len) ? NULL : p;
}
#else
static void __user *userspace_stack_buffer(const void *d, size_t len)
{
	if (!current->mm)
		return NULL;

	volatile unsigned long start_stack = current->mm->start_stack;
	unsigned int step = 32;

start_loop:;
	char __user *p = (void __user *)(start_stack - step - len);
	if (IS_ENABLED(CONFIG_KSU_DEBUG))
		pr_info("%s: start_stack: %lx p: %lx len: %zu\n", __func__, start_stack, (unsigned long)p, len );

	if (!copy_to_user(p, d, len))
		return p;

	step = step + step;

	if (step <= 2048)
		goto start_loop;

	return nullptr;
}
#endif

static char __user *sh_user_path(void)
{
	constexpr char sh_path[16] = SH_PATH;
	return userspace_stack_buffer(sh_path, sizeof(sh_path));
}

static char __user *ksud_user_path(void)
{
	constexpr char ksud_path[16] = KSUD_PATH;
	return userspace_stack_buffer(ksud_path, sizeof(ksud_path));
}

#if !defined(CONFIG_KSU_TAMPER_SYSCALL_TABLE) && defined(KSU_CAN_USE_JUMP_LABEL)
DEFINE_STATIC_KEY_TRUE(ksud_sucompat_key);
static inline void ksu_sucompat_enable_branch()
{
	pr_info("su_compat: enable sucompat branches\n");
	static_branch_enable(&ksud_sucompat_key);
	smp_mb();
}
static inline void ksu_sucompat_disable_branch()
{
	pr_info("su_compat: remove sucompat branches\n");
	static_branch_disable(&ksud_sucompat_key);
	smp_mb();
}
#else
static inline void ksu_sucompat_enable_branch() { } // no-op
static inline void ksu_sucompat_disable_branch() { } // no-op
#endif

static noinline bool __ksu_is_allow_uid_copy(uid_t uid)
{
	return __ksu_is_allow_uid(uid);
}

static __always_inline bool is_su_allowed(const void **ptr_to_check)
{
#ifndef CONFIG_KSU_TAMPER_SYSCALL_TABLE
#ifdef KSU_CAN_USE_JUMP_LABEL
	// read as: if not 'likely' disabled
	if (!!!static_branch_likely(&ksud_sucompat_key))
		return false;
#else
	if (!ksu_su_compat_enabled)
		return false;
#endif // KSU_CAN_USE_JUMP_LABEL
#endif

	// put ret hot on insn pipeline
	if (likely(ksu_is_seccomp_enabled()))
		return false;

	// pass through tagged task from setuid hook
	if (test_thread_flag(TIF_KSU_MANAGED))
		goto check_ptr;

	// see seccomp check above
	// so if its root but not ksu domain, deny, see __ksu_is_allow_uid_for_current
	// actually, we can likely skip this step?
	uid_t uid = current_uid().val;
	if (!!uid)
		goto uid_check;

	if (!is_ksu_domain())
		return false;
	goto check_ptr;

uid_check:
#if defined(CONFIG_KSU_ENABLE_FULL_UID_CHECKS)
	if (!__ksu_is_allow_uid(uid))
		return false;
#elif defined(CONFIG_KSU_SHELL_HAS_SU_ALWAYS)
	/**
	 * NOTE: if shell always has su anyway, and full uid checks are disabled, 
	 * we can skip all these checks. this goto is for explicitness / code styel
	 */
	 goto check_ptr;
	 __builtin_unreachable();
#else /* default behavior */
	/**
	 * NOTE: shell has its seccomp disabled, so we only need
	 * to check for this thing. short-circuit if not shell! 
	 * as we allow apps on setuid lsm by disabling seccomp
	 *
	 */
	if (likely(uid != 2000))
		goto check_ptr;

	/**
	 * use our noinline copy. only shell falls through this. nbd that
	 * it opens up a stack frame .having small code around here is worth
	 */
	if (!__ksu_is_allow_uid_copy(uid))
		return false;
#endif /* default behavior */
check_ptr:
	// first check the pointer-to-pointer
	if (unlikely(!ptr_to_check))
		return false;

	// now dereference pointer-to-pointer to check actual pointer
	if (unlikely(!*ptr_to_check))
		return false;

	return true;
}

static __always_inline void ksu_sucompat_user_common(const char __user **filename_user, const char *syscall_name)
{
	uintptr_t buf;
	constexpr char su[16] = SU_PATH;

	// sugar prep
	uintptr_t *su_p = (uintptr_t *)su;
	uintptr_t __user *fn_p = (uintptr_t __user *)untagged_addr(*(char **)filename_user);

	static_assert(sizeof(SU_PATH) + 1 == 16);

	// cheaper than prefaulting (fault_in_readable, fault_in_pages_readable)
	__builtin_prefetch(fn_p);

	/*
	 * it seems this is actually the slowest part, so we peek last word first to speed it up
	 * NOTE: get_user rets EFAULT on err, so if we are copying a pointer that points to nothing, 
	 * we also detect that and ret fast
	 *
	 * first read overreads, reading 8 bytes, "bin/su\0?" /  4 bytes, "su\0?" when we only need 7/3
	 * but this is fine as we are guaranteed alignment, hardware provides trailing garbeg
	 * if it is specially crafted and hits a page guard, we just get EFAULT anyway
	 *
	 * on 64-bit we do this in 2 word compare, 4 on 32-bit, little endian only!
	 *
	 */

#ifdef CONFIG_64BIT
	if (get_user(buf, &fn_p[1]))
		return;

	if (likely((buf & 0x00FFFFFFFFFFFFFFUL) != (su_p[1] & 0x00FFFFFFFFFFFFFFUL)))
		return;
#else
	if (get_user(buf, &fn_p[3]))
		return;

	if (likely((buf & 0x00FFFFFFUL) != (su_p[3] & 0x00FFFFFFUL)))
		return;

	if (unlikely(get_user(buf, &fn_p[2])))
		return;

	if (buf != su_p[2])
		return;

	if (unlikely(get_user(buf, &fn_p[1])))
		return;

	if (unlikely(buf != su_p[1]))
		return;
#endif
	// last word
	if (unlikely(get_user(buf, &fn_p[0])))
		return;

	if (unlikely(buf != su_p[0]))
		return;

	if (!__builtin_strcmp(syscall_name, "sys_faccessat"))
		write_sulog('a');
	if (!__builtin_strcmp(syscall_name, "sys_newfstatat"))
		write_sulog('s');
	if (!__builtin_strcmp(syscall_name, "sys_execve"))
		write_sulog('x');
	if (!__builtin_strcmp(syscall_name, "sys_execveat"))
		write_sulog('x');

	// escalate if execve
	if (!!__builtin_strcmp(syscall_name, "sys_execve") && !!__builtin_strcmp(syscall_name, "sys_execveat"))
		goto no_escalate;

#ifdef CONFIG_KSU_FEATURE_SULOG
	ksu_sulog_emit(KSU_SULOG_EVENT_SUCOMPAT, NULL, NULL, GFP_KERNEL);
#endif
	if (!!escape_with_root_profile())
		return;

	ksu_install_su_fd(); // ksu#3679

	// NOTE: we only check file existence, not exec success!
	struct path kpath;
	if (!!kern_path("/data/adb/ksud", 0, &kpath))
		goto no_ksud;

	path_put(&kpath);
	pr_info("su_compat: %s su->ksud!%s\n", syscall_name, (is_compat_task()) ? " [compat]" : "" );
	*filename_user = ksud_user_path();
	return;

no_ksud:
no_escalate:
	pr_info("su_compat: %s su->sh!%s\n", syscall_name, (is_compat_task()) ? " [compat]" : "" );
	*filename_user = sh_user_path();
	return;

}

// sys_faccessat
SUCOMPAT_HOOK_TYPE ksu_handle_faccessat(int *dfd, const char __user **filename_user, int *mode, int *__unused_flags)
{
	if (!is_su_allowed((const void **)filename_user))
		return 0;

	ksu_sucompat_user_common(filename_user, "sys_faccessat");
	return 0;
}

// sys_newfstatat, sys_fstat64
SUCOMPAT_HOOK_TYPE ksu_handle_stat(int *dfd, const char __user **filename_user, int *flags)
{
	if (!is_su_allowed((const void **)filename_user))
		return 0;

	ksu_sucompat_user_common(filename_user, "sys_newfstatat");
	return 0;
}

// sys_execve, compat_sys_execve
SUCOMPAT_HOOK_TYPE ksu_handle_sys_execve(const char __user **filename_user, void *argv, void *envp)
{
#ifdef CONFIG_KSU_FEATURE_ADBROOT
	ksu_adb_root_execve_user((void *)filename_user, (void *)envp);
#endif
	if (!is_su_allowed((const void **)filename_user))
		return 0;

	ksu_sucompat_user_common(filename_user, "sys_execve");
	return 0;
}

// sys_execveat, compat_sys_execveat
SUCOMPAT_HOOK_TYPE ksu_handle_sys_execveat(int *fd, const char __user **filename_user, void *argv, void *envp, int *flags)
{
#ifdef CONFIG_KSU_FEATURE_ADBROOT
	ksu_adb_root_execve_user((void *)filename_user, (void *)envp);
#endif
	if (!is_su_allowed((const void **)filename_user))
		return 0;

	ksu_sucompat_user_common(filename_user, "sys_execveat");
	return 0;
}

static __always_inline void ksu_sucompat_kernel_common(int *restrict fd, void **restrict filename_ptr, void *restrict argv, void *restrict envp, int *restrict flags, const char *function_name)
{
#ifdef CONFIG_KSU_FEATURE_ADBROOT
	ksu_adb_root_execve_kernel((void *)filename_ptr, (void *)envp);
#endif
	if (!is_su_allowed((const void **)filename_ptr))
		return;

	if (!!fd && fd != (int *)AT_FDCWD && *fd != AT_FDCWD)
		return;

	if (!!flags && !!*flags)
		return;

	constexpr char su[16] = SU_PATH;

#if 0 // defined(KSU_HAS_INT128)
// https://godbolt.org/z/j8Yovv6bE
	uint128_t *su128 = (uint128_t *)su;
	uint128_t *fn128 = (uint128_t *)*(char **)filename_ptr;
	const uint128_t mask = make128const(0x00FFFFFFFFFFFFFFULL, 0xFFFFFFFFFFFFFFFFULL);
	if (likely((*fn128 & mask) != (*su128 & mask)))
		return;
#endif
	// getname_flags pads this so nothing to worry about, dereference with confidence!
	uint64_t *su_p = (uint64_t *)su;
	uint64_t *fn_p = (uint64_t *)*(char **)filename_ptr;

	if (likely((fn_p[1] & 0x00FFFFFFFFFFFFFFULL) != (su_p[1] & 0x00FFFFFFFFFFFFFFULL)))
		return;

	if (unlikely(fn_p[0] != su_p[0]))
		return;

	// we only handle execve here after removing vfs_statx hook for >= 6.1
	write_sulog('x');

#ifdef CONFIG_KSU_FEATURE_SULOG
	ksu_sulog_emit(KSU_SULOG_EVENT_SUCOMPAT, NULL, NULL, GFP_KERNEL);
#endif
	if (!!escape_with_root_profile())
		return;

	ksu_install_su_fd(); // ksu#3679

	// NOTE: we only check file existence, not exec success!
	struct path kpath;
	if (!!kern_path("/data/adb/ksud", 0, &kpath))
		goto no_ksud;

	path_put(&kpath);
	pr_info("su_compat: %s su->ksud!%s\n", function_name, (is_compat_task()) ? " [compat]" : "");
	constexpr char ksud[16] = KSUD_PATH;
	memcpy_inline(*filename_ptr, ksud, sizeof(ksud));
	return;

no_ksud:
	pr_info("su_compat: %s su->sh!%s\n", function_name, (is_compat_task()) ? " [compat]" : "" );
	constexpr char sh[16] = SH_PATH;
	memcpy_inline(*filename_ptr, sh, sizeof(sh));
	return;
}

struct filename; // take note: struct filename *filename, for do_execveat_common / do_execve_common on >= 3.14
SUCOMPAT_HOOK_TYPE ksu_handle_execveat(int *fd, struct filename **filename_ptr, void *argv, void *envp, int *flags)
{
	void *struct_filename = *(void **)filename_ptr;
	if (IS_ERR(struct_filename)) // see getname_flags
		return 0;

#if LINUX_VERSION_CODE >= KERNEL_VERSION(3, 14, 0)
	static_assert(offsetof(struct filename, name) == 0);
#endif

	// first member of struct filename is char *name.
	// char *filename = *(char **)struct_filename;
	ksu_sucompat_kernel_common(fd, (void **)struct_filename, argv, envp, flags, "do_execveat_common");
	return 0;
}

// take note: char *filename, for do_execve_common on < 3.14
SUCOMPAT_HOOK_TYPE ksu_legacy_execve_sucompat(const char **filename_ptr, void *argv, void *envp)
{
	ksu_sucompat_kernel_common((int *)AT_FDCWD, (void **)filename_ptr, argv, envp, 0, "do_execve_common");
	return 0;
}

#ifdef CONFIG_KSU_TAMPER_SYSCALL_TABLE
static void syscall_table_sucompat_enable();
static void syscall_table_sucompat_disable();
#else
#define syscall_table_sucompat_enable() do { } while (0)
#define syscall_table_sucompat_disable() do { } while (0)
#endif

static void ksu_sucompat_enable()
{

	ksu_sucompat_enable_branch();
	syscall_table_sucompat_enable();

	ksu_su_compat_enabled = true;
	pr_info("%s: hooks enabled: exec, faccessat, stat\n", __func__);
}

static void ksu_sucompat_disable()
{

	ksu_sucompat_disable_branch();
	syscall_table_sucompat_disable();

	ksu_su_compat_enabled = false;
	pr_info("%s: hooks disabled: exec, faccessat, stat\n", __func__);
}

static int su_compat_feature_get(u64 *value)
{
	*value = ksu_su_compat_enabled ? 1 : 0;
	return 0;
}

static int su_compat_feature_set(u64 value)
{
	bool enable = value != 0;

	if (enable == ksu_su_compat_enabled) {
		pr_info("su_compat: no need to change\n");
	return 0;
	}

	if (enable) {
		ksu_sucompat_enable();
	} else {
		ksu_sucompat_disable();
	}

	ksu_su_compat_enabled = enable;
	pr_info("su_compat: set to %d\n", enable);

	return 0;
}

static const struct ksu_feature_handler su_compat_handler = {
	.feature_id = KSU_FEATURE_SU_COMPAT,
	.name = "su_compat",
	.get_handler = su_compat_feature_get,
	.set_handler = su_compat_feature_set,
};

// sucompat: permited process can execute 'su' to gain root access.
void __init ksu_sucompat_init()
{
	if (ksu_register_feature_handler(&su_compat_handler)) {
		pr_err("Failed to register su_compat feature handler\n");
	}

	tiny_sulog_init_heap();
}

void __exit ksu_sucompat_exit()
{
	ksu_unregister_feature_handler(KSU_FEATURE_SU_COMPAT);
}

static __always_inline void ksu_handle_setresuid_cred(struct cred *new, const struct cred *old)
{
	if (!new || !old)
		return;

	uid_t new_uid = ksu_get_uid_t(new->uid);
	uid_t old_uid = ksu_get_uid_t(old->uid);

	// old process is not root, ignore it.
	if (unlikely(!!old_uid))
		return;

	if (IS_ENABLED(CONFIG_KSU_DEBUG))
		pr_info("handle_setresuid from %d to %d\n", old_uid, new_uid);

	// we dont have those new fancy things upstream has
	// lets just do the original thing where we disable seccomp
	if (unlikely(is_uid_manager(new_uid)))
		goto install_ksu_fd;

	if (ksu_is_allow_uid_for_current(new_uid))
		goto kill_seccomp;

	// Handle kernel umount
	ksu_handle_umount(new, old);
	return;

install_ksu_fd:
	pr_info("install fd for manager: %d\n", new_uid);
	ksu_install_fd();

kill_seccomp:
	disable_seccomp();
	set_thread_flag(TIF_KSU_MANAGED); // sucompat fast-path
	return;
}

